#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.hookshotDrowned)]
    public class HookshotDrowned : EntityBehaviourDefinition
    {
        public HookshotDrowned(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.AddBuff<HookshotUserBuff>();
        }
    }
}